"""Quality-page composition based on the supplied UI, without unverified badges."""
quality=f'''<section class="capabilities-hero quality-hero"><div class="capabilities-hero-photo">{img(1603,'Techno Printpack team reviewing production details together',eager=True)}</div><div class="capabilities-hero-angle"></div><div class="container"><div>{label('QUALITY & COMPLIANCE')}<h1>Quality Packaging<br>Starts with the Details</h1><p>Define the materials, structure, dimensions and print requirements for packaging that suits your product.</p><div class="capabilities-breadcrumb" aria-label="Breadcrumb"><a href="index.html"><i data-lucide="house" aria-hidden="true"></i>Home</a><span aria-hidden="true">›</span><span>Quality</span></div></div></div></section>
<section class="quality-themes"><div class="container">{''.join(f'<a href="{url}"><i data-lucide="{icon}" aria-hidden="true"></i><h2>{title}</h2></a>' for icon,title,url in [('award','Consistent Requirements','#quality-process'),('layers','Material Suitability','#quality-process'),('shield-check','Clear Specifications','#quality-process'),('leaf','Responsible Choices','#certifications')])}</div></section>
<section class="quality-assurance" id="quality-process"><div class="container quality-process-layout"><div class="quality-photo-frame"><span class="quality-photo-accent accent-top" aria-hidden="true"></span><span class="quality-photo-accent accent-bottom" aria-hidden="true"></span><div>{img(1529,'Corrugated packaging materials being handled inside Techno Printpack')}</div></div><div class="quality-process-copy">{label('OUR QUALITY APPROACH')}<h2>A Structured Quality Conversation</h2><p>Agree what matters before production: the board, fit, artwork and functional requirements. Use the following checkpoints to build your packaging specification with our team.</p><ol class="quality-process-steps">{''.join(f'<li><a href="quotation.html"><i data-lucide="{icon}" aria-hidden="true"></i><span>{title}</span></a>'+('<b aria-hidden="true">→</b>' if i<4 else '')+'</li>' for i,(icon,title) in enumerate([('package','Board & Materials'),('ruler','Dimensions & Fit'),('printer','Artwork & Print'),('box','Structure & Use'),('circle-check','Agreed Specification')]))}</ol><p class="quality-process-note">Test methods, tolerances and acceptance criteria are confirmed for your project; no particular test or inspection programme is assumed.</p></div></div></section>
<section class="quality-standards" id="certifications"><div class="container quality-standards-layout"><div>{label('CERTIFICATIONS & DOCUMENTATION')}<h2>Confirm the Standards<br>for Your Project</h2><p>Request the current documents relevant to your packaging, materials and intended use.</p></div><div class="quality-document-grid">{''.join(f'<details><summary><i data-lucide="{icon}" aria-hidden="true"></i><span>{title}</span><b aria-hidden="true">+</b></summary><div><p>{desc}</p><a href="contact.html">Ask our team <span aria-hidden="true">↗</span></a></div></details>' for icon,title,desc in [('file-check-2','Certification Documents','The company website describes Techno Industries as ISO-certified. Request current certificates and confirm the covered entity, site, scope and validity. Current documents have not been verified for publication here.'),('layers','Material Suitability','Share product-contact, moisture, handling or other material requirements. Ask for documentation applicable to the selected material and intended use.'),('shield-check','Agreed Quality Criteria','Discuss the dimensions, artwork, structural requirements and acceptance criteria for your order. Confirm any required test methods and supporting results directly.'),('leaf','Responsible Choices','Discuss material selection and resource considerations with the team. Request product-specific evidence for any environmental claim required by your project.')])}</div></div><div class="container"><p class="quality-doc-note">Certification and compliance documents are available to request from the team. No certification badge, test result or environmental certification is presented as verified on this page.</p></div></section>
<section class="quality-cta-section"><div class="container"><div class="capability-cta quality-cta"><div class="capability-cta-photo">{img(1529,'Corrugated board and packaging materials')}</div><i class="quality-cta-symbol" data-lucide="package" aria-hidden="true"></i><div><h2>Packaging Around Your Requirements</h2><p>Share your product, quantity and quality requirements with our team.</p></div>{btn('Request a Quote','quotation.html')}</div></div></section>'''
pages['quality']=('Quality & Certifications','Explore packaging specification checkpoints and request current quality, material and certification documentation from Techno Printpack.',quality)
